mapper.select:
SELECT id, tenant_key, name, status, created_at, updated_at, created_by, updated_by, is_default, tenant_mode_origin
FROM public.tenants
WHERE tenant_key = #{tenantKey}

SELECT id, tenant_key, name, status, created_at, updated_at, created_by, updated_by, is_default, tenant_mode_origin
FROM public.tenants
WHERE id = #{id}

SELECT COUNT(*) FROM public.tenants
( LOWER(name) LIKE LOWER(CONCAT('%', #{search}, '%')) OR LOWER(tenant_key) LIKE LOWER(CONCAT('%', #{search}, '%')) )
AND status = #{status}

mapper.update:
UPDATE public.tenants
SET name       = #{name},
    status     = #{status, typeHandler=org.apache.ibatis.type.EnumTypeHandler},
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
WHERE tenant_key = #{tenantKey}

mapper.select:
SELECT id, tenant_key, name, status, created_at, updated_at, created_by, updated_by, is_default, tenant_mode_origin
FROM public.tenants
WHERE status = #{status}

mapper.update:
UPDATE public.tenants
SET status     = #{status},
    updated_at = #{updatedAt}
WHERE tenant_key = #{tenantKey}
